<!--
  GearSwap Atelier · the Bags view of My character (bags.ts): the bags as tiles, where the character stands, the
  state of the tidy-up, the bag shown with its search, filters and items, or the plan's cards. The list takes what is
  left of the window (bags_view.js bvFit, after each drawing).

  @file    atelier/src/screens/perso/Bags.svelte
  @author  ejouanchicot
-->
<script lang="ts">
  import Box from '../../components/Box.svelte';
  import type {BagsView, BagTile, BagItem, PlanCard} from './bags';

  let {view}: {view: BagsView} = $props();
  // the list is given the window's height left once it is drawn
  $effect(() => { view; requestAnimationFrame(bvFit); });
</script>

{#snippet tile(b: BagTile)}<button class="bvtile {b.cls}" data-bagsel={b.name} aria-pressed={b.pressed} title={b.title}><b>{b.name}</b>{#if b.kind === 'bag'}<span class="bvnum">{b.used}<i>/{b.max}</i></span><span class="bvbar"><i style="width:{b.pct}%"></i></span>{:else}<span class="bvnum">{b.used}</span><span class="bvbar"></span>{/if}<small class="bvrole" title={b.role.title}><span>{b.role.short}</span>{#if b.role.bad}<i title={b.role.bad.title}>{b.role.bad.n}</i>{/if}</small></button>{/snippet}
{#snippet item(r: BagItem)}<div class="bvitem" class:split={r.split} class:bad={r.bad} class:picked={r.picked} class:unk={r.unk} data-bpick={r.id} title={r.title}>{@html r.iconHtml}<b>{r.name}</b>{#if r.badLine}<small class="bvx">{r.badLine}</small>{/if}{#if r.augs}<small class="bva">{r.augs}</small>{/if}{#if r.use}{#if 'none' in r.use}<small class="bvu none">{r.use.none}</small>{:else}<small class="bvu">{#if r.use.lock}<i class="ls">{r.use.lock}</i>{/if}{#each r.use.jobs as j (j)}<i>{j}</i>{/each}{#if r.use.more}<i class="more">+{r.use.more}</i>{/if}{#if r.use.cfg}<i class="cfg">{r.use.cfg}</i>{/if}</small>{/if}{/if}{#if r.places}<small class="bvw">{r.places.prefix}{#each r.places.bags as b, i (i)}<i>{b}</i>{/each}</small>{/if}{#if r.n > 1}<em>×{r.n}</em>{/if}</div>{/snippet}
{#snippet card(c: PlanCard)}<div class="bpcard {c.cls}" title={c.tip}><div class="bphead"><h4>{c.title}</h4>{#if c.free}<b class="bpbig">{c.need}</b>{:else}<b class="bpbig" title={c.nowTip}>{c.now}<i>/{c.room}</i></b>{/if}</div>{#if !c.free}<span class="bpgauge"><i style="width:{c.pct}%"></i></span>{/if}<p class="bpverdict">{#if c.verdict.ok}<b class="ok">{c.verdict.text}</b>{#if c.verdict.left}<span>{c.verdict.left}</span>{/if}{:else}<b class="bad">{c.verdict.text}</b>{/if}</p>{#if c.flow}<p class="bpmove">{c.flow}</p>{/if}<p class="bpfoot">{#each c.bags as b, i (i)}<i>{b}</i>{/each}{#if c.mule}<button class="linkbtn" data-bpmule title={c.mule.title}>{c.mule.text}</button>{/if}<span class="sp"></span>{#each c.see as s (s.cat)}<button class="linkbtn" data-bpsee={s.cat} title={s.title}>{s.label}</button>{/each}</p></div>{/snippet}

{#if view.none !== null}
  <div class="placeholder"><p>{view.none}</p></div>
{:else}
  <div class="bagsview"><p class="muted small bvat">{view.at} <button class="linkbtn" data-gtuto title={view.tuto.title}>{view.tuto.text}</button></p>{#if view.place}{@const p = view.place}<p class="bvplace" title={p.title}><i>{p.here}</i><b>{p.zone}</b>{#each p.chips as c, i (i)}<span class={c.cls} title={c.title || undefined}>{c.text}</span>{/each}{#if p.run}<button class="btn plrun" data-plrun title={p.run.title}>{p.run.text}</button>{/if}<button class="linkbtn" data-plwhere title={p.where.title}>{p.where.text}</button></p>{#if view.toast}<p class="toast">{view.toast}</p>{/if}{/if}<div class="bvtop"><div class="bvgroup"><!-- svelte-ignore a11y_missing_content (an empty title over the two first tiles, as high as the groups' titles) --><h4>&nbsp;</h4><div class="bvtiles"><button class="bvtile all" data-bagsel="all" aria-pressed={view.all.pressed} title={view.all.title}><b>{view.all.label}</b><span class="bvnum">{view.all.total}<i>/{view.all.room}</i></span><span class="bvbar"><i style="width:{view.all.pct}%"></i></span><small class="bvrole">{view.all.sub}</small></button><button class="bvtile plan" data-bagsel="plan" aria-pressed={view.plan.pressed} title={view.plan.title}><b>{view.plan.label}</b><span class="bvnum"></span><span class="bvbar"></span><small class="bvrole">{view.plan.sub}</small></button></div></div>{#each view.groups as g (g.place)}<div class="bvgroup {g.place} {g.state}"><h4><span>{g.title}</span>{#if g.mark}<em title={g.mark.title}>{g.mark.text}</em>{/if}</h4><div class="bvtiles">{#each g.tiles as b (b.name)}{@render tile(b)}{/each}</div></div>{/each}</div><div class="bpstatus {view.status.state}"><span class="bpmain"><i aria-hidden="true">{view.status.icon}</i><b>{view.status.title}</b><small>{view.status.small}</small></span>{#each view.status.chips as c (c.key)}{#if c.attr === 'data-bpunk'}<button class="bpchip warn" data-bpunk><b>{c.n}</b>{c.label}</button>{:else if c.attr === 'data-bpwrong'}<button class="bpchip warn" data-bpwrong><b>{c.n}</b>{c.label}</button>{:else}<button class="bpchip " data-bpsee={c.value}><b>{c.n}</b>{c.label}</button>{/if}{/each}{#if view.status.unsaved}<small class="bpunsaved" title={view.status.unsaved.title}>{view.status.unsaved.text}</small>{/if}<button class="btn ghost" data-bagsel="plan">{view.status.planText}</button></div>
    {#if view.body.kind === 'plan'}
      {@const pl = view.body}
      <Box cls="g-attr wide" title={pl.title}><div id="bvlist" class="bvlist"><div class="bpplan"><div class="bpsendbar"><p class="muted small" title={pl.whyTitle}>{pl.why}</p><button class="btn" data-bpopen disabled={!pl.open.n} title={pl.open.title}>{pl.open.text}</button></div>{#if pl.toast}<p class="toast">{pl.toast}</p>{/if}<div class="bpcards">{#each pl.cards as c (c.key)}{@render card(c)}{/each}</div><p class="bpnote" class:warn={pl.note.warn}>{pl.note.text}{#if pl.note.unk}{' '}<button class="linkbtn" data-bpunk>{pl.note.unk}</button>{/if}{#if pl.note.porter}{' ' + pl.note.porter}{/if}</p></div></div></Box>
    {:else}
      {@const li = view.body}
      {#snippet roles()}{#each li.roles as r (r.part)}<label class="bvpick" title={r.title}>{r.label}<select data-bagrole={r.bag} data-part={r.part}>{#each r.options as o (o.value)}<option value={o.value} selected={o.selected}>{o.label}</option>{/each}</select></label>{/each}{/snippet}
      <Box cls="g-attr wide" title={li.title} extra={li.roles.length ? roles : undefined}><div class="bvbar2"><input id="bagq" class="tgq" type="search" value={li.filters.q} placeholder={li.filters.placeholder} autocomplete="off"><span class="modseg">{#each li.filters.cats as c (c.value)}<button data-bagcat={c.value} aria-pressed={c.pressed}>{c.label}</button>{/each}</span><span class="modseg bvuse" title={li.filters.use.title}>{#each li.filters.use.options as o (o.value)}<button data-baguse={o.value} aria-pressed={o.pressed}>{o.label}</button>{/each}</span><label class="bvpick" title={li.filters.pc.title}>{li.filters.pc.label}<select data-bagpc>{#each li.filters.pc.options as o (o.value)}<option value={o.value} selected={o.selected}>{o.label}</option>{/each}</select></label><button class="modsw" role="switch" aria-checked={li.filters.dup.on} data-bagdup title={li.filters.dup.title}><span class="sw" class:on={li.filters.dup.on} aria-hidden="true"></span><b>{li.filters.dup.label}</b></button></div><div id="bpsel">{#if !li.sel.n}<div class="bpsel idle"><span class="muted small">{li.sel.pickTip}</span><span class="sp"></span><button class="btn ghost" data-bpall>{li.sel.all}</button></div>{:else}<div class="bpsel"><b>{li.sel.title}</b>{#each li.sel.cats as c (c.value)}<button class="bpcat" data-bptag={c.value}>{c.label}</button>{/each}<button class="bpcat auto" data-bptag="" title={li.sel.auto.title}>{li.sel.auto.text}</button><span class="sp"></span><button class="btn ghost" data-bpall>{li.sel.all}</button><button class="btn ghost" data-bpnone>{li.sel.none}</button></div>{/if}</div><div id="bvlist" class="bvlist">{#if li.list.none}<p class="muted bvnone">{li.list.none}</p>{:else}<p class="bvcount muted small">{li.list.count}</p>{#each li.list.cats as c (c.name)}<h4 class="bvcat">{c.name}<small>{c.count}</small></h4><div class="bvgrid">{#each c.items as r (r.id + '|' + r.augs)}{@render item(r)}{/each}</div>{/each}{/if}</div></Box>
    {/if}
  </div>
{/if}
